import limited_client as robot, numpy as np
print('STATUS',robot.status())
for c in (0,2,1):
 o=robot.observe(camera=c); r=o['robot']; print('\nCAM',c,'TCP',r['tcp_position'],'GRIP',r['gripper_positions'],'Q',r['joint_positions'])
 K=o['intrinsic']; T=o['camera_to_world']; pc=np.linalg.inv(T)@np.r_[r['tcp_position'],1.]
 uv=K@pc[:3]; print('TCP pixel',uv[:2]/uv[2],'camxyz',pc[:3])
 if c in (0,2):
  d=o['depth_m']; rgb=o['rgb'];
  for u,v in ([(210,320),(220,320),(230,320),(240,320),(250,320),(220,335),(240,335)] if c==0 else [(230,245),(240,245),(250,245),(240,255),(240,265)]):
   z=float(np.nanmedian(d[max(v-2,0):v+3,max(u-2,0):u+3])); w=T@np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1.])
   print('pixel',u,v,'rgb',rgb[v,u].tolist(),'z',z,'world',w[:3].tolist())
